<?php require_once 'config.php';require_role('provider');$title='تعديل الملف';$s=$pdo->prepare('SELECT * FROM provider_profiles WHERE user_id=?');$s->execute([user()['id']]);$p=$s->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){$titlep=trim($_POST['title']??'');$spec=trim($_POST['specialization']??'');$desc=trim($_POST['description']??'');$price=(float)($_POST['price']??0);if($titlep===''||$spec===''||$price<0){flash('تحققي من البيانات والسعر.');go('provider_edit.php');}$pdo->prepare('UPDATE provider_profiles SET title=?,specialization=?,description=?,consultation_price=? WHERE user_id=?')->execute([$titlep,$spec,$desc,$price,user()['id']]);flash('تم تحديث الملف.');go('provider_dashboard.php');}require 'includes/header.php';?><div class="formbox"><h1>تعديل ملف مقدم الخدمة</h1><form method="post"><label>عنوان الملف</label><input name="title" required value="<?=h($p['title'])?>"><label>التخصص</label><input name="specialization" required value="<?=h($p['specialization'])?>"><label>نبذة عن الخدمة</label><textarea name="description"><?=h($p['description'])?></textarea><label>سعر الاستشارة بالدينار الليبي</label><input type="number" name="price" min="0" step="0.01" required value="<?=h($p['consultation_price'])?>"><div class="btnrow"><button class="btn">حفظ التعديلات</button></div></form></div><?php require 'includes/footer.php';?>
